-- iJob MySQL 8 notification send audit. IDs are generated by the application.

CREATE TABLE ifj_notify_send_log (
    id BIGINT NOT NULL,
    source_type VARCHAR(32) NOT NULL,
    correlation_id VARCHAR(64) NULL,
    operator_id VARCHAR(128) NULL,
    target_type VARCHAR(32) NULL,
    target_id BIGINT NULL,
    instance_id BIGINT NULL,
    notify_binding_id BIGINT NULL,
    notify_config_id BIGINT NOT NULL,
    notify_type VARCHAR(32) NULL,
    result VARCHAR(32) NOT NULL,
    failure_code VARCHAR(64) NULL,
    failure_summary VARCHAR(500) NULL,
    duration_ms BIGINT NULL,
    create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_ifj_notify_send_log PRIMARY KEY (id),
    INDEX idx_ifj_notify_send_log_create_time (create_time, id),
    INDEX idx_ifj_notify_send_log_config_time (notify_config_id, create_time),
    INDEX idx_ifj_notify_send_log_target_time (target_type, target_id, create_time),
    INDEX idx_ifj_notify_send_log_instance_time (instance_id, create_time),
    INDEX idx_ifj_notify_send_log_result_time (result, create_time)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;
